const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const mayfield = ee.Geometry.Point([-88.63, 36.74]);
  const buffer = mayfield.buffer(5000); // 5km buffer around Mayfield

  // 2. Data Acquisition & Check
  // Try monthly VIIRS data for November 2021
  const novCollection = ee.ImageCollection('VIIRS/DNB/MONTHLY_V1/VCMSLCFG')
    .filterDate('2021-11-01', '2021-11-30')
    .filterBounds(mayfield);

  const novSize = novCollection.size().getInfo();
  console.log(`November 2021 images: ${novSize}`);

  if (novSize === 0) {
    console.log("No November data found.");
    console.log("<answer>C1</answer>");
    return;
  }

  // For December 10-12, use daily VIIRS data
  const decCollection = ee.ImageCollection('VIIRS/DNB/MONTHLY_V1/VCMSLCFG')
    .filterDate('2021-12-01', '2021-12-31')
    .filterBounds(mayfield);

  const decSize = decCollection.size().getInfo();
  console.log(`December 2021 images: ${decSize}`);

  if (decSize === 0) {
    console.log("No December data found.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing
  const novImage = novCollection.mean().select('avg_rad');
  const decImage = decCollection.mean().select('avg_rad');

  // Check pixel counts
  const novCount = novImage.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: buffer,
    scale: 1000,
    maxPixels: 1e9
  }).get('avg_rad').getInfo();

  const decCount = decImage.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: buffer,
    scale: 1000,
    maxPixels: 1e9
  }).get('avg_rad').getInfo();

  console.log(`November valid pixels: ${novCount}`);
  console.log(`December valid pixels: ${decCount}`);

  if (novCount === 0 || decCount === 0) {
    console.log("No valid pixels after processing.");
    console.log("<answer>C2</answer>");
    return;
  }

  // 4. Calculation
  const novMean = novImage.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: buffer,
    scale: 1000,
    maxPixels: 1e9
  }).get('avg_rad').getInfo();

  const decMean = decImage.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: buffer,
    scale: 1000,
    maxPixels: 1e9
  }).get('avg_rad').getInfo();

  console.log(`November 2021 mean radiance: ${novMean}`);
  console.log(`December 2021 mean radiance: ${decMean}`);

  // 5. Validation & Final Answer
  if (novMean === null || decMean === null || isNaN(novMean) || isNaN(decMean)) {
    console.log("Calculation failed - null or NaN values.");
    console.log("<answer>C3</answer>");
    return;
  }

  const difference = novMean - decMean;
  console.log(`Difference (Nov - Dec): ${difference.toFixed(4)}`);

  if (novMean > decMean) {
    console.log("November brightness was higher than December.");
    console.log("<answer>A</answer>");
  } else {
    console.log("November brightness was NOT higher than December.");
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
